export function safeViewerURL(value){try{const url=new URL(value);return url.origin==='https://skinshotter.com'&&!url.username&&!url.password&&/^\/(rifles|pistols|smgs|heavy|knives|gloves)\/[a-z0-9-]+\/[a-z0-9-]+$/.test(url.pathname)&&!url.search&&!url.hash?url.href:null}catch{return null}}
export function createSkinInspector(dialog){
 const stage=dialog.querySelector('#catalogViewerStage'),image=dialog.querySelector('.catalog-detail-media'),status=dialog.querySelector('#catalogViewerStatus'),three=dialog.querySelector('#catalogView3D'),still=dialog.querySelector('#catalogViewImage'),link=dialog.querySelector('#catalogExternalViewer'),retry=dialog.querySelector('#catalogViewerRetry'),fullscreen=dialog.querySelector('#catalogViewerFullscreen');let frame=null,url=null,title='';
 function clear(){if(document.fullscreenElement===stage)document.exitFullscreen().catch(()=>{});if(frame){frame.src='about:blank';frame.remove();frame=null}stage.replaceChildren();delete stage.dataset.loaded}
 function show3D(){clear();if(!url){showImage();return}image.hidden=true;stage.hidden=false;fullscreen.hidden=false;three.setAttribute('aria-pressed','true');still.setAttribute('aria-pressed','false');status.textContent='Cargando visor de Skinshotter…';retry.hidden=false;
  frame=document.createElement('iframe');frame.title='Visor 3D de '+title+' · Skinshotter';frame.allow='fullscreen; autoplay';frame.allowFullscreen=true;frame.referrerPolicy='strict-origin-when-cross-origin';frame.setAttribute('sandbox','allow-scripts allow-same-origin allow-popups allow-popups-to-escape-sandbox allow-downloads allow-pointer-lock');frame.src=url;const current=frame;frame.onload=()=>{if(frame!==current)return;stage.dataset.loaded='true';status.textContent='Visor de Skinshotter · Arrastra para girar y usa la rueda para acercarte.'};frame.onerror=()=>{if(frame===current)status.textContent='No se pudo abrir el visor. Reintenta o abre la skin en Skinshotter.'};stage.append(frame);
 }
 function showImage(){clear();image.hidden=false;stage.hidden=true;fullscreen.hidden=true;three.setAttribute('aria-pressed','false');still.setAttribute('aria-pressed','true');retry.hidden=true;status.textContent=url?'Imagen de referencia del catálogo.':'Esta skin todavía no tiene un enlace 3D disponible.'}
 fullscreen.onclick=()=>stage.requestFullscreen?.().catch(()=>{status.textContent='No se pudo activar pantalla completa. Puedes seguir usando el visor en este menú.'});
 three.onclick=show3D;still.onclick=showImage;retry.onclick=show3D;dialog.addEventListener('close',clear);
 return{open(skin,viewer){clear();title=skin.weapon+' · '+skin.name;url=safeViewerURL(viewer);three.disabled=!url;link.hidden=!url;if(url)link.href=url;else link.removeAttribute('href');dialog.querySelector('#catalogSavedSkin').textContent='Se guardará: '+title;url?show3D():showImage()},dispose:clear};
}
